WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessions), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS session_start_flag_tier, SORT_ARRAY(COLLECT_SET(device)) AS device_list, SUM(CASE WHEN browser = 'Chrome' THEN session_no ELSE 0 END) AS chrome_session_no, AVG(session_start_flag) FILTER (WHERE country = 'UK') AS uk_avg_session_start_flag FROM islands GROUP BY ROLLUP (CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END) ORDER BY session_start_flag_tier DESC NULLS LAST;
